<!-- 编辑器任务反馈：集中显示通知、构建与导入进度，提供取消、重试及诊断复制。 -->
<template>
  <Teleport to="body">
    <div v-if="feedback.banner" class="feedback-banner" role="status"><span>{{ feedback.banner }}</span><UiButton :label="t('close')" @click="feedback.banner = ''" icon="close" /></div>
    <div class="toast-stack" aria-live="polite" aria-atomic="false"><article v-for="toast in feedback.toasts" :key="toast.id" :class="toast.kind"><span>{{ toast.message }}</span><button v-if="toast.action" @click="toast.action(); dismissToast(toast.id)">{{ toast.actionLabel }}</button><UiButton :label="t('close')" @click="dismissToast(toast.id)" icon="close" /></article></div>
    <section v-if="state.statusCenterOpen" class="status-center" role="dialog" :aria-label="t('statusCenter')">
      <header><div><strong>{{ t('statusCenter') }}</strong><small>{{ activeCount }} {{ t('activeTasks') }}</small></div><UiButton :label="t('close')" @click="state.statusCenterOpen = false" icon="close" /></header>
      <div class="task-list">
        <article v-if="build.phase !== 'idle'" :class="build.phase"><div><strong>{{ t('build') }}</strong><small>{{ build.message }}</small></div><progress :value="build.percent" max="100"></progress><span>{{ build.percent }}%</span></article>
        <article v-for="job in imports.jobs" :key="`import-${job.id}`" :class="job.status"><div><strong>{{ job.name }}</strong><small>{{ t(`importStatus_${job.status}`) }}</small></div><progress :value="job.progress" max="1"></progress><button v-if="!['complete','failed','cancelled'].includes(job.status)" @click="cancelAssetImport(job.id)">{{ t('cancel') }}</button><code v-else-if="job.error">{{ job.error }}</code></article>
        <article v-for="task in feedback.tasks" :key="task.id" :class="task.status"><div><strong>{{ task.title }}</strong><small>{{ task.detail || task.status }}</small></div><progress v-if="task.progress !== null" :value="task.progress" max="1"></progress><span v-else class="spinner"></span><div class="task-actions"><button v-if="task.cancel && ['queued','running'].includes(task.status)" @click="cancelTask(task.id)">{{ t('cancel') }}</button><button v-if="task.retry && task.status === 'failed'" @click="retryTask(task.id)">{{ t('retry') }}</button></div><details v-if="task.error || task.logs.length || task.resources.length"><summary>{{ t('taskDetails') }}</summary><code v-if="task.error">{{ task.error }}</code><pre v-if="task.logs.length">{{ task.logs.join('\n') }}</pre><nav v-if="task.resources.length"><button v-for="resource in task.resources" :key="resource.label" @click="openResource(resource)">{{ resource.label }}</button></nav></details></article>
        <p v-if="!hasTasks">{{ t('noBackgroundTasks') }}</p>
      </div>
      <footer><button @click="copy">{{ copied ? t('copied') : t('copyDiagnostics') }}</button><button @click="clearFinishedTasks">{{ t('clearFinished') }}</button></footer>
    </section>
  </Teleport>
</template>
<script setup lang="ts">
import UiButton from '../ui/components/UiButton.vue'
import { computed, ref } from 'vue'
import { t } from '../i18n'
import { editorState as state } from '../store/editor'
import { importPipelineState as imports, cancelAssetImport } from '../assets/importPipeline'
import { buildProgress as build } from '../runtime/buildSettings'
import { cancelTask, clearFinishedTasks, dismissToast, feedbackDiagnostics, feedbackState as feedback, retryTask } from '../runtime/editorFeedback'
import { faultDiagnostics, reportRecoverableError } from '../runtime/faultCenter'
import type { TaskResourceLink } from '../runtime/editorFeedback'
const copied = ref(false)
const activeCount = computed(/** 合计运行或排队的后台任务、未结束导入以及正在工作的构建任务。 */ () => feedback.tasks.filter(/** 判断后台任务是否仍在运行或等待执行。 */ item => ['running','queued'].includes(item.status)).length + imports.jobs.filter(/* 返回 ['complete','failed','cancelled'].includes(item.status) 的逻辑取反结果。 */ item => !['complete','failed','cancelled'].includes(item.status)).length + (['validating','packing','exporting'].includes(build.phase) ? 1 : 0))
const hasTasks = computed(/** 判断后台任务、导入记录或构建状态中是否存在可展示的内容。 */ () => feedback.tasks.length > 0 || imports.jobs.length > 0 || build.phase !== 'idle')
/** 复制任务和故障诊断，短暂显示复制成功状态；剪贴板失败通过可恢复错误中心报告。 */ async function copy() { try { await navigator.clipboard.writeText(`${feedbackDiagnostics()}\n\n${faultDiagnostics()}`); copied.value = true; setTimeout(/** 复制成功提示到期后恢复默认按钮状态。 */ () => { copied.value = false }, 1500) } catch (error) { reportRecoverableError(error, 'Copy status diagnostics') } }
/** 优先执行任务资源自带操作，否则以隔离来源的新窗口打开资源链接。 */ function openResource(resource: TaskResourceLink) { if (resource.action) resource.action(); else if (resource.href) window.open(resource.href, '_blank', 'noopener,noreferrer') }
</script>
<style scoped>.feedback-banner{position:fixed;top:var(--ui-control-height);left:50%;transform:translateX(-50%);z-index:2250;width:min(80ch,calc(100vw - var(--ui-space-xl)));display:flex;gap:var(--ui-space-sm);align-items:center;padding:var(--ui-space-sm);border:1px solid var(--warning);background:var(--surface-popover)}.feedback-banner>span{flex:1;min-width:0;overflow-wrap:anywhere}.toast-stack{position:fixed;right:var(--ui-space-sm);bottom:calc(var(--ui-control-height) + var(--ui-space-sm));z-index:2200;width:min(48ch,calc(100vw - var(--ui-space-xl)));display:grid;gap:var(--ui-space-xs);pointer-events:none}.toast-stack article{display:flex;align-items:center;gap:var(--ui-space-xs);padding:var(--ui-space-sm);border:1px solid var(--border-strong);border-left:2px solid var(--accent);background:var(--surface-popover);box-shadow:var(--shadow-md);pointer-events:auto}.toast-stack article.success{border-left-color:var(--success)}.toast-stack article.warning{border-left-color:var(--warning)}.toast-stack article.error{border-left-color:var(--danger)}.toast-stack span{min-width:0;flex:1;overflow-wrap:anywhere}.status-center{position:fixed;right:var(--ui-space-sm);bottom:calc(var(--ui-control-height) + var(--ui-space-xs));z-index:2100;width:min(64ch,calc(100vw - var(--ui-space-xl)));max-height:calc(100vh - 3 * var(--ui-control-height));display:flex;flex-direction:column;border:1px solid var(--border-strong);border-radius:var(--radius-dialog);background:var(--surface-popover);box-shadow:var(--shadow-lg)}.status-center>header{display:flex;align-items:center;justify-content:space-between;gap:var(--ui-space-sm);padding:var(--ui-space-sm);border-bottom:1px solid var(--border-subtle)}.status-center>header>div{display:grid}.status-center small{color:var(--text-muted);font-size:var(--type-caption)}.task-list{min-height:0;overflow:auto;padding:var(--ui-space-sm)}.task-list>article{display:grid;grid-template-columns:minmax(0,1fr) minmax(8ch,25%) auto;gap:var(--ui-space-xs);align-items:center;padding-block:var(--ui-space-sm);border-bottom:1px solid var(--border-subtle)}.task-list>article>div:first-child{min-width:0;display:grid}.task-list small{overflow-wrap:anywhere}.task-list progress{width:100%}.task-list code,.task-list details{grid-column:1/-1;overflow-wrap:anywhere}.task-list>p{text-align:center;color:var(--text-muted);padding:var(--ui-space-lg)}.task-list details pre{max-height:180px;overflow:auto;padding:var(--ui-space-sm);background:var(--input-bg);white-space:pre-wrap}.task-list details nav,.status-center>footer{display:flex;gap:var(--ui-space-xs);flex-wrap:wrap}.status-center>footer{padding:var(--ui-space-sm);justify-content:flex-end;border-top:1px solid var(--border-subtle)}.spinner{width:var(--ui-icon-size);height:var(--ui-icon-size);border:2px solid var(--border-strong);border-top-color:var(--accent);border-radius:50%;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spinner{animation:none}}</style>
